// Decides WHICH threads to process, for 3 ways of starting the workflow:
//  1. Streamlit "Analyse a thread": webhook body {url}  -> just that thread
//  2. Streamlit "Fetch" button:     webhook body {limit} -> pending rows in thread_urls
//  3. Daily schedule: newly listed community threads (keyword pre-filtered), max 8
//  (4. Manual run in n8n -> pending rows, default limit)
const RE = /support\.google\.com\/photos\/thread\/(\d+)/;
let limit = 50, direct = null;
try {
  const w = $('Webhook (from Streamlit)1').first();
  const body = (w && w.json && w.json.body) || {};
  if (body.limit) limit = Number(body.limit);
  if (body.url) direct = [String(body.url).trim()];
} catch (e) { /* not started by the webhook */ }
try {
  const s = $('Extract listing links').first();
  if (s && s.json && s.json._trigger === 'schedule') { direct = s.json.candidates || []; limit = 8; }
} catch (e) { /* not started by the schedule */ }

const rows = $input.all().map(i => i.json);
const done = new Set();
for (const r of rows) {
  const m = String(r.url || '').match(RE);
  if (m && String(r.status || '').trim().toLowerCase() === 'done') done.add(m[1]);
}
const source = direct !== null ? direct.map(u => ({ url: u, status: '' })) : rows;
const seen = new Set();
const out = [];
for (const r of source) {
  const sheetUrl = String(r.url || '').trim();
  const status = String(r.status || '').trim().toLowerCase();
  const m = sheetUrl.match(RE);
  if (!m || status === 'done' || done.has(m[1]) || seen.has(m[1])) continue;   // skip invalid, done, duplicates
  seen.add(m[1]);
  out.push({ json: { sheet_url: sheetUrl, thread_id: m[1], url: `https://support.google.com/photos/thread/${m[1]}` } });
  if (out.length >= limit) break;
}
return out;

// Builds the Groq request for one thread. Groq uses the OpenAI-compatible format.
// Models: 'openai/gpt-oss-120b' (best quality) | 'llama-3.3-70b-versatile' | 'llama-3.1-8b-instant' (fastest, biggest daily quota)
const MODEL = 'openai/gpt-oss-120b';

const loop = $('Loop Over Threads1').item.json;
const title = String($json.title || '').replace(/\s*-\s*Google Photos Community\s*$/i, '').trim();
let text = String($json.page_text || '').replace(/\s+/g, ' ').trim();
text = text.slice(0, 8000);    // ~3K tokens per call keeps us under Groq's free-tier per-minute limit

const SYSTEM = "You are a UX researcher analysing public posts from the Google Photos Help Community.\nResearch question: why do people fail to retrieve an old photo they remember but cannot precisely describe?\n\nYou get one thread (question + replies, with page boilerplate mixed in). Focus on the ORIGINAL POSTER's problem.\nReturn ONLY a JSON object with exactly these keys:\n{\n  \"is_retrieval_problem\": true/false,   // true ONLY if the user is trying to FIND/LOCATE an existing photo or video. Backup, sync, deletion/recovery, storage, editing, sharing settings = false\n  \"photo_type\": \"people_event | place_trip | screenshot | document | product_item | food | other | unknown\",\n  \"intent\": \"share | practical_info | nostalgia | work | unknown\",\n  \"cues_remembered\": [\"what the user DID remember, in their words: e.g. 'trip to Goa', 'my cousin', 'last winter'\"],\n  \"cues_forgotten\": [\"what they did NOT know: e.g. 'exact date', 'place name'\"],\n  \"query_tried\": [\"exact search terms or methods they tried, verbatim where possible\"],\n  \"failure_stage\": \"expression | understanding | evaluation | refinement | not_applicable\",\n  \"workaround\": [\"anything they or repliers did instead: scrolling, WhatsApp, albums, asking friends\"],\n  \"key_quote\": \"the single most telling sentence from the original poster, verbatim, max 30 words\",\n  \"summary\": \"one line, max 20 words\"\n}\nfailure_stage definitions:\n- expression: user cannot turn what they remember into a search (does not know what words/filters to use)\n- understanding: user gave clues but search returned nothing or the wrong things\n- evaluation: results came back but too many / too similar to spot the right photo\n- refinement: first search failed and the user did not know how to adjust it\n- not_applicable: not a retrieval problem\nUse [] or \"unknown\" when the thread does not say. Never invent details.";

return { json: {
  url: loop.url,
  sheet_url: loop.sheet_url,
  title,
  chars: text.length,
  payload: {
    model: MODEL,
    temperature: 0,
    max_completion_tokens: 1500,
    response_format: { type: 'json_object' },
    ...(MODEL.startsWith('openai/gpt-oss') ? { reasoning_effort: 'low' } : {}),
    messages: [
      { role: 'system', content: SYSTEM },
      { role: 'user', content: `Thread title: ${title}\n\nThread text:\n${text}` },
    ],
  },
}};

// Turns the Grok answer into one flat row for the `insights` tab.
const prev = $('Build AI request1').item.json;
let t = {};
try {
  t = JSON.parse($json.choices[0].message.content);
} catch (e) {
  t = { summary: 'PARSE_ERROR: ' + String(e).slice(0, 100) };
}
const list = (v) => Array.isArray(v) ? v.join('; ') : (v ?? '');

return { json: {
  source: 'google_photos_community',
  url: prev.url,
  title: prev.title,
  is_retrieval_problem: t.is_retrieval_problem === true ? 'TRUE' : 'FALSE',
  photo_type: t.photo_type || 'unknown',
  intent: t.intent || 'unknown',
  cues_remembered: list(t.cues_remembered),
  cues_forgotten: list(t.cues_forgotten),
  query_tried: list(t.query_tried),
  failure_stage: t.failure_stage || 'not_applicable',
  workaround: list(t.workaround),
  key_quote: t.key_quote || '',
  summary: t.summary || '',
  scraped_at: new Date().toISOString(),
}};

// Extracts ONLY the original poster's question (no replies, no author name).
// 1) schema.org QAPage data  2) the page's thread_view data  3) fallback: plain body text.
// Never executes page scripts; only parses saved data.
const html = String($json.data || '');
const id = $('Loop Over Threads1').item.json.thread_id;
const plain = t => typeof t === 'string' && t.trim().length > 0 && !/<\/?[A-Za-z][^>]*>/.test(t);
const idFromUrl = v => { if (typeof v !== 'string') return null;
  const m = /^https:\/\/support\.google\.com\/photos\/thread\/(\d+)(?:\/[^/?#]*)?\/?(?:\?[^#]*)?(?:#.*)?$/.exec(v); return m ? m[1] : null; };
function decodeLiteral(s) {
  let r = ''; const esc = {n:'\n', r:'\r', t:'\t', b:'\b', f:'\f', '\\':'\\', "'":"'", '"':'"', '/':'/'};
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== '\\') { r += s[i]; continue; }
    const e = s[++i];
    if (e === 'x' || e === 'u') { const w = e === 'x' ? 2 : 4; const d = s.slice(i + 1, i + 1 + w);
      if (d.length !== w || !/^[0-9a-f]+$/i.test(d)) throw Error('bad literal'); r += String.fromCharCode(parseInt(d, 16)); i += w; }
    else if (Object.prototype.hasOwnProperty.call(esc, e)) r += esc[e]; else throw Error('bad literal');
  }
  return r;
}
let title = null, text = null, kind = null;
// 1) QAPage structured data
const qs = [];
const visit = v => { if (!v || typeof v !== 'object') return; if (Array.isArray(v)) { v.forEach(visit); return; }
  if ([].concat(v['@type'] || []).includes('QAPage') && v.mainEntity && !Array.isArray(v.mainEntity)) qs.push(v.mainEntity);
  if (v['@graph']) visit(v['@graph']); };
for (const m of html.matchAll(/<script\b[^>]*type\s*=\s*["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script\s*>/gi)) {
  try { visit(JSON.parse(m[1])); } catch (_) {}
}
if (qs.length === 1 && plain(qs[0].text) && (!qs[0].url || idFromUrl(qs[0].url) === id)) {
  title = typeof qs[0].name === 'string' ? qs[0].name : null; text = qs[0].text; kind = 'original_post';
}
// 2) thread_view bootstrap data
if (!text) {
  const decl = [];
  for (const s of html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi)) {
    if (/\bsrc\s*=/i.test(s[1])) continue;
    for (const m of s[2].matchAll(/\bvar\s+thread_view\s*=\s*'((?:\\[\s\S]|[^'\\])*)'\s*;/g)) decl.push(m[1]);
  }
  if (decl.length === 1) {
    try {
      const view = JSON.parse(decodeLiteral(decl[0]));
      const thread = Array.isArray(view) ? view[1] : null;
      const info = Array.isArray(thread) ? thread[0] : null;
      if (Array.isArray(info) && String(info[0]) === id && Array.isArray(thread) && thread.length >= 14 &&
          typeof thread[8] === 'string' && thread[8].trim() && plain(thread[12])) {
        title = thread[8]; text = thread[12]; kind = 'original_post';
      }
    } catch (_) {}
  }
}
// 3) Fallback: visible body text (question + replies)
if (!text) {
  const t = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(html);
  title = t ? t[1] : '';
  const body = (/<body[^>]*>([\s\S]*)<\/body>/i.exec(html) || [null, html])[1];
  text = body.replace(/<(script|style|noscript|svg|header|footer|nav)\b[\s\S]*?<\/\1>/gi, ' ')
             .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"');
  kind = 'page_text_fallback';
}
return { json: { title: String(title || '').trim(), page_text: String(text || '').replace(/\s+/g, ' ').trim(), text_kind: kind } };

// Daily discovery: reads the community's latest-threads page and keeps likely
// retrieval threads, judged by the URL slug (cheap pre-filter before the AI tags them).
const html = String($input.first().json.data || '');
const KEEP = /(find|search|locat|looking-for|where-(is|are)|cant-see|can-t-see|not-show|show-up|face|people|place|map|old-photo|memor)/i;
const DROP = /(delet|recover|restor|trash|backup|back-up|storage|sync|locked-folder|refund|subscription|payment)/i;
const seen = new Set(); const candidates = []; let listed = 0;
for (const m of html.matchAll(/\/photos\/thread\/(\d+)(?:\/([a-z0-9-]+))?/gi)) {
  const id = m[1], slug = (m[2] || '').toLowerCase();
  if (seen.has(id)) continue; seen.add(id); listed++;
  if (!slug || DROP.test(slug) || !KEEP.test(slug)) continue;
  candidates.push(`https://support.google.com/photos/thread/${id}/${slug}`);
}
return [{ json: { _trigger: 'schedule', listed, kept: candidates.length, candidates } }];
